#!/usr/bin/env python3
"""gen_humanities_shelf.py — the Humanities & Social Sciences full-shelf planning pass book
generator (owner directive, 2026-11-16: "create all things like you did for
engineering do it for humanities and social science and languages section").
Same method and machinery as gen_engineering_shelf.py (2026-11-16) and the
Mathematics (2026-11-10) / Computer Science (2026-11-15) passes.

16 books across six branches — History (2), Polity & Governance (4),
Society (3), Mind (3), Earth (2), Culture & Past (2). Six backlog lines
fold honestly onto shelf homes (Ancient+Medieval+Modern → indian-history;
Human+Physical Geography → geography; Heritage Studies →
archaeology-and-heritage-studies; Art History owned here with the future
Arts shelf cross-referencing it).

16 books promoted to src/data/library/books/humanities/<slug>/book.ts,
status 'planned', ZERO lessons written — 157 chapters / 620 planned
lessons in total. The authored plan data (chapters, summaries,
planned-lesson titles, positioning, research notes) lives in this script;
the emitter below writes the house-format book.ts files. Idempotent:
re-running regenerates every file deterministically.

Evidence base: docs/research/HUMANITIES_TOC_SURVEY.md (the UPSC GS-I/II/IV
registers + nine optional-subject registers + the UGC NET subject register
+ the College Board AP units + the CLAT register as the exam anchors; URLs
in SOURCE_LOG.md). Gate: scripts/verify-humanities-shelf-planning.ts.
"""
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OUT_DIR = os.path.join(ROOT, "src", "data", "library", "books", "humanities")

BOOKS = []


def book(export, bid, title, shelf_note, subtitle, level, description,
         accent, positioning, research, chapters):
    BOOKS.append(dict(export=export, bid=bid, title=title, shelf_note=shelf_note,
                      subtitle=subtitle, level=level, description=description,
                      accent=accent, positioning=positioning, research=research,
                      chapters=chapters))


def ch(slug, title, summary, lessons):
    return dict(slug=slug, title=title, summary=summary, lessons=lessons)


